from itertools import combinations

PRICE_PER_BOOK = 8.0
DISCOUNTS = {
    1: 0.00,
    2: 0.05,
    3: 0.10,
    4: 0.20,
    5: 0.25,
}

def _group_price(size):
    return size * PRICE_PER_BOOK * (1.0 - DISCOUNTS[size])

def total(basket):
    """
    Calculate the lowest possible price for a basket of books from a 5-book series.

    The basket is expected to be either:
    - a list of book ids (integers) where each element is 1..5 (or 0..4), e.g. [1,1,2,3,4,5]
    - OR a list of counts per volume of length 5, e.g. [2,2,2,1,1]

    The function will compute the optimal grouping into sets of distinct books
    to maximize the discount, and return the total price as a float rounded to 2 decimals.
    """
    # Normalize input to counts of length 5
    if not isinstance(basket, list):
        raise TypeError("basket must be a list")

    # Detect if basket is already counts-per-volume: length 5 and sum != length (likely counts)
    if len(basket) == 5 and all(isinstance(x, int) for x in basket) and sum(basket) != len(basket):
        counts = list(basket)
        if any(x < 0 for x in counts):
            raise ValueError("counts must be non-negative")
        # ensure length exactly 5
        if len(counts) != 5:
            raise ValueError("counts list must have length 5")
    else:
        # Treat basket as list of book ids
        counts = [0] * 5
        for b in basket:
            if not isinstance(b, int):
                raise TypeError("book ids must be integers")
            # Accept ids 1..5 or 0..4
            if 1 <= b <= 5:
                counts[b - 1] += 1
            elif 0 <= b <= 4:
                counts[b] += 1
            else:
                raise ValueError("book ids must be in range 0..4 or 1..5")

    # Memoized recursion over states (tuple of counts)
    memo = {}

    def recurse(state):
        key = tuple(state)
        if key in memo:
            return memo[key]
        if all(c == 0 for c in state):
            memo[key] = 0.0
            return 0.0

        best = float('inf')
        positive_indices = [i for i, c in enumerate(state) if c > 0]
        max_group = len(positive_indices)
        # try all possible group sizes from 1..max_group
        for group_size in range(1, max_group + 1):
            # try every combination of distinct books of this size
            for combo in combinations(positive_indices, group_size):
                next_state = list(state)
                for idx in combo:
                    next_state[idx] -= 1
                cost = _group_price(group_size) + recurse(next_state)
                if cost < best:
                    best = cost

        memo[key] = best
        return best

    result = recurse(counts)
    # round to 2 decimal places for monetary value
    return round(result + 1e-8, 2)
